helpers.log('Starting SQL Database node');

const operation = node.properties.operation.value;
const databaseType = node.properties.databaseType.value;
const connectionString = node.properties.connectionString?.value;
const sqlitePath = node.properties.sqlitePath?.value || './database.db';
let query = node.properties.query?.value;
const table = node.properties.table?.value;
let dataToWrite = node.properties.data?.value;
const whereClause = node.properties.where?.value;
let parametersConfig = node.properties.parameters?.value || [];
const returnRows = node.properties.returnRows?.value !== false;

helpers.log(`Operation: ${operation}`);
helpers.log(`Database type: ${databaseType}`);

// Resolve template variables
if (typeof dataToWrite === 'string') {
  if (dataToWrite === '{{data}}') {
    dataToWrite = data;
  } else {
    try {
      dataToWrite = JSON.parse(dataToWrite);
    } catch (e) {
      // Keep as is
    }
  }
}

// Process parameters based on format
let parameters = [];
if (typeof parametersConfig === 'string') {
  // Legacy JSON array format
  try {
    parameters = JSON.parse(parametersConfig);
    helpers.log('Parsed legacy JSON parameters');
  } catch (e) {
    helpers.warn('Failed to parse parameters as JSON, using empty array');
    parameters = [];
  }
} else if (Array.isArray(parametersConfig)) {
  // New fixedCollection format
  helpers.log(`Processing ${parametersConfig.length} parameter(s)`);
  parameters = parametersConfig.map((param, idx) => {
    let value = param.value;
    const type = param.type || 'string';

    // Type conversion based on specified type
    switch (type) {
      case 'number':
        value = Number(value);
        break;
      case 'boolean':
        value = value === 'true' || value === true;
        break;
      case 'null':
        value = null;
        break;
      case 'string':
      default:
        value = String(value);
        break;
    }

    helpers.log(`Parameter ${idx + 1}: ${type} = ${JSON.stringify(value)}`);
    return value;
  });
}

// Note: This is a template implementation
// In production, you would use actual database drivers:
// - better-sqlite3 for SQLite
// - pg for PostgreSQL  
// - mysql2 for MySQL

try {
  switch (operation) {
    case 'query': {
      if (!query) {
        return {
          path: 'error',
          error: 'SQL query is required'
        };
      }

      // Simulated query execution
      // In production, replace with actual database connection
      helpers.log(`Executing query: ${query}`);
      helpers.log(`Parameters: ${JSON.stringify(parameters)}`);

      return {
        success: true,
        operation: 'query',
        message: 'Query execution simulated. Install database driver for production use.',
        query,
        parameters,
        databaseType,
        note: 'Install: npm install better-sqlite3 (for SQLite), pg (for PostgreSQL), or mysql2 (for MySQL)'
      };
    }

    case 'insert': {
      if (!table || !dataToWrite) {
        return {
          path: 'error',
          error: 'Table name and data are required'
        };
      }

      // Build INSERT query
      const rows = Array.isArray(dataToWrite) ? dataToWrite : [dataToWrite];
      const columns = Object.keys(rows[0] || {});
      const placeholders = columns.map(() => '?').join(', ');
      const insertQuery = `INSERT INTO ${table} (${columns.join(', ')}) VALUES (${placeholders})`;

      helpers.log(`Built query: ${insertQuery}`);

      return {
        success: true,
        operation: 'insert',
        message: 'Insert simulated. Install database driver for production use.',
        query: insertQuery,
        table,
        rowCount: rows.length,
        databaseType
      };
    }

    case 'update': {
      if (!table || !dataToWrite) {
        return {
          path: 'error',
          error: 'Table name and data are required'
        };
      }

      // Build UPDATE query
      const columns = Object.keys(dataToWrite);
      const setClause = columns.map(col => `${col} = ?`).join(', ');
      const updateQuery = `UPDATE ${table} SET ${setClause}${whereClause ? ` WHERE ${whereClause}` : ''}`;

      helpers.log(`Built query: ${updateQuery}`);

      return {
        success: true,
        operation: 'update',
        message: 'Update simulated. Install database driver for production use.',
        query: updateQuery,
        table,
        whereClause,
        databaseType
      };
    }

    case 'delete': {
      if (!table) {
        return {
          path: 'error',
          error: 'Table name is required'
        };
      }

      // Build DELETE query
      const deleteQuery = `DELETE FROM ${table}${whereClause ? ` WHERE ${whereClause}` : ''}`;

      helpers.log(`Built query: ${deleteQuery}`);

      if (!whereClause) {
        helpers.warn('DELETE without WHERE clause will delete all rows!');
      }

      return {
        success: true,
        operation: 'delete',
        message: 'Delete simulated. Install database driver for production use.',
        query: deleteQuery,
        table,
        whereClause,
        warning: whereClause ? null : 'No WHERE clause - would delete all rows',
        databaseType
      };
    }

    default:
      return {
        path: 'error',
        error: `Unknown operation: ${operation}`
      };
  }
} catch (error) {
  helpers.error('SQL operation failed:', error);
  return {
    path: 'error',
    error: error.message,
    details: error.stack
  };
}
